/**
 * IRCTC & Indian Railways Official Cancellation Refund Engine
 * Based on Railway Passengers (Cancellation of Ticket and Refund of Fare) Rules
 * Commercial Circular No. 43 of 2015 & IRCTC Tatkal Cancellation Policy
 */

export interface RefundSlab {
  key: 'gt48' | '48to12' | '12to4' | 'lt4';
  label: string;
  timeWindow: string;
  deductionAmount: number | null;
  refundAmount: number | null;
  percentageText: string;
  isActive: boolean;
  notes?: string;
}

export interface RefundCalculationResult {
  pnrNumber: string;
  fareAvailable: boolean;
  departureTimeAvailable: boolean;
  isTatkal: boolean;
  isConfirmed: boolean;
  isWaitlistedOrRAC: boolean;
  ticketFare: number | null;
  passengerCount: number;
  travelClass: string;
  quota: string;
  hoursUntilDeparture: number | null;
  currentRefund: number | null;
  currentDeduction: number | null;
  currentSlabLabel: string;
  currentSlabWindow: string;
  timeUntilDepartureText: string;
  explanation: string;
  tatkalAdvisory?: string;
  slabs: RefundSlab[];
}

/**
 * Official Indian Railways clerkage charge per unconfirmed WL / RAC passenger
 * (Commercial Circular No. 43 of 2015, Rule 7: ₹60 + 5% GST for AC classes; ₹60 for non-AC)
 */
export const WL_RAC_CLERKAGE_CHARGE = 60;

/**
 * Standard minimum flat cancellation charges per passenger (> 48h before departure)
 */
export const MIN_FLAT_CHARGES: Record<string, { charge: number; hasGst: boolean }> = {
  '1A': { charge: 240, hasGst: true },
  'EC': { charge: 240, hasGst: true },
  'EA': { charge: 240, hasGst: true },
  '2A': { charge: 200, hasGst: true },
  'FC': { charge: 200, hasGst: false },
  '3A': { charge: 180, hasGst: true },
  '3E': { charge: 180, hasGst: true },
  'CC': { charge: 180, hasGst: true },
  'SL': { charge: 120, hasGst: false },
  '2S': { charge: 60, hasGst: false },
};

/**
 * Estimated default class fare when not returned by upstream API
 */
export const DEFAULT_CLASS_FARES: Record<string, number> = {
  '1A': 2950,
  'EC': 2400,
  '2A': 1850,
  '3A': 1350,
  '3E': 1200,
  'CC': 850,
  'SL': 645,
  '2S': 195,
};

/**
 * Normalizes travel class from code or coach prefix
 */
export function inferTravelClass(classCode?: string, coach?: string): string {
  if (classCode) {
    const clean = classCode.toUpperCase().trim();
    if (MIN_FLAT_CHARGES[clean]) return clean;
    if (clean.includes('SLEEPER') || clean === 'S') return 'SL';
    if (clean.includes('3A') || clean.includes('3 TIER') || clean.includes('THIRD')) return '3A';
    if (clean.includes('2A') || clean.includes('2 TIER') || clean.includes('SECOND AC')) return '2A';
    if (clean.includes('1A') || clean.includes('FIRST AC')) return '1A';
    if (clean.includes('CC') || clean.includes('CHAIR')) return 'CC';
    if (clean.includes('2S') || clean.includes('SECOND')) return '2S';
    if (clean.includes('3E') || clean.includes('ECONOMY')) return '3E';
  }

  if (coach) {
    const c = coach.toUpperCase().trim();
    if (c.startsWith('HA') || c.startsWith('H')) return '1A';
    if (c.startsWith('A')) return '2A';
    if (c.startsWith('B')) return '3A';
    if (c.startsWith('M')) return '3E';
    if (c.startsWith('C')) return 'CC';
    if (c.startsWith('D')) return '2S';
    if (c.startsWith('S')) return 'SL';
    if (c.startsWith('E')) return 'EC';
  }

  return 'SL';
}

export interface CalculateRefundParams {
  pnr: string;
  journeyDate: string;
  departureTime?: string;
  fare?: number | null;
  travelClass?: string;
  quota?: string;
  passengers: Array<{
    booking_status?: string;
    current_status?: string;
  }>;
  chartStatus?: string;
}

function parseRefundDepartureDateTime(journeyDateStr: string, departureTimeStr?: string): Date | null {
  const cleanDate = (journeyDateStr || '').trim();
  if (!cleanDate) return null;

  const timeSource = (departureTimeStr || '').trim() || (/\d{1,2}:\d{2}/.test(cleanDate) ? cleanDate : '');
  const timeMatch = timeSource.match(/(\d{1,2}):(\d{2})(?::\d{2})?\s*([APap][Mm])?/);
  if (!timeMatch) return null;

  let hours = parseInt(timeMatch[1], 10);
  const minutes = parseInt(timeMatch[2], 10);
  const meridiem = timeMatch[3]?.toUpperCase();
  if (meridiem === 'PM' && hours < 12) hours += 12;
  if (meridiem === 'AM' && hours === 12) hours = 0;

  const MONTHS: Record<string, number> = {
    jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5,
    jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11,
  };

  const namedMatch = cleanDate.match(/(\d{1,2})[\s\-]+([A-Za-z]{3,})[\s\-]+(\d{4})/);
  if (namedMatch && MONTHS[namedMatch[2].slice(0, 3).toLowerCase()] !== undefined) {
    const dt = new Date(
      parseInt(namedMatch[3], 10),
      MONTHS[namedMatch[2].slice(0, 3).toLowerCase()],
      parseInt(namedMatch[1], 10),
      hours,
      minutes,
      0
    );
    return isNaN(dt.getTime()) ? null : dt;
  }

  if (/^\d{4}[\-\/]\d{1,2}[\-\/]\d{1,2}/.test(cleanDate)) {
    const dParts = cleanDate.split(/[\-\/T ]/);
    const dt = new Date(parseInt(dParts[0], 10), parseInt(dParts[1], 10) - 1, parseInt(dParts[2], 10), hours, minutes, 0);
    return isNaN(dt.getTime()) ? null : dt;
  }

  if (/^\d{1,2}[\-\/]\d{1,2}[\-\/]\d{4}/.test(cleanDate)) {
    const dParts = cleanDate.split(/[\-\/ ]/);
    const dt = new Date(parseInt(dParts[2], 10), parseInt(dParts[1], 10) - 1, parseInt(dParts[0], 10), hours, minutes, 0);
    return isNaN(dt.getTime()) ? null : dt;
  }

  const fallback = new Date(cleanDate);
  if (!isNaN(fallback.getTime())) {
    fallback.setHours(hours, minutes, 0, 0);
    return fallback;
  }
  return null;
}

export function calculateCancellationRefund(params: CalculateRefundParams): RefundCalculationResult {
  const {
    pnr,
    journeyDate,
    departureTime,
    passengers = [],
    chartStatus = 'Chart Not Prepared'
  } = params;

  const paxCount = Math.max(1, passengers.length);

  // 1. Detect Class & Quota (F-P0-07: never fabricate default fare, PT quota, or 21:20 departure time)
  const firstPax = passengers[0] || {};
  const curStatus = (firstPax.current_status || '').toUpperCase();
  const bookStatus = (firstPax.booking_status || '').toUpperCase();

  // Extract coach if available (e.g. from CNF/S6/1/LB)
  const parts = curStatus.split('/').map(s => s.trim());
  const extractedCoach = parts.length >= 3 && !/^\d+$/.test(parts[1]) ? parts[1] : undefined;
  const resolvedClass = inferTravelClass(params.travelClass, extractedCoach);

  // Detect Quota strictly from authoritative fields
  const quotaRaw = (params.quota || '').trim().toUpperCase();
  const isTatkal =
    quotaRaw === 'TQ' ||
    quotaRaw === 'PT' ||
    quotaRaw.includes('TATKAL') ||
    bookStatus.includes('TQ') ||
    bookStatus.includes('CK') ||
    curStatus.includes('TQ') ||
    curStatus.includes('CK');

  // Detect per-passenger confirmation & queue status (supports mixed CNF + WL/RAC & NOSB children)
  const isNosbStatus = (s: string) => /\bNOSB\b/i.test(s);
  const isCanStatus = (s: string) =>
    !isNosbStatus(s) && /\b(CANCELLED|CANCELED|CAN|MOD|RELEASED|REL)\b/i.test(s);
  const isCnfStatus = (s: string) =>
    !isCanStatus(s) && !isNosbStatus(s) && (s.includes('CNF') || s.includes('CONFIRM'));
  const isWlRacStatus = (s: string) =>
    !isCanStatus(s) && !isNosbStatus(s) && !isCnfStatus(s) && (s.includes('WL') || s.includes('RAC'));

  let cnfPaxCount = 0;
  let wlRacPaxCount = 0;
  let nosbPaxCount = 0;
  let canPaxCount = 0;

  for (const p of passengers) {
    const s = (p.current_status || '').toUpperCase();
    if (isNosbStatus(s)) nosbPaxCount++;
    else if (isCanStatus(s)) canPaxCount++;
    else if (isCnfStatus(s)) cnfPaxCount++;
    else if (isWlRacStatus(s)) wlRacPaxCount++;
  }

  const isConfirmed = cnfPaxCount > 0;
  const isWaitlistedOrRAC = wlRacPaxCount > 0;
  const isPureWlRac = isWaitlistedOrRAC && !isConfirmed;
  const isMixedCnfAndWlRac = isWaitlistedOrRAC && isConfirmed;
  const isAllCancelled =
    passengers.length > 0 &&
    canPaxCount === passengers.length &&
    cnfPaxCount === 0 &&
    wlRacPaxCount === 0 &&
    nosbPaxCount === 0;

  // Honest fare resolution: never substitute fake ₹645 when ticket fare is absent
  const fareAvailable = typeof params.fare === 'number' && Number.isFinite(params.fare) && params.fare > 0;
  const baseFare = fareAvailable ? (params.fare as number) : null;

  // 2. Parse Departure Countdown honestly without silent 21:20 or 31.9h fallback
  const depDate = parseRefundDepartureDateTime(journeyDate, departureTime);
  const departureTimeAvailable = depDate !== null;
  const hoursUntilDeparture = depDate !== null ? (depDate.getTime() - Date.now()) / (1000 * 60 * 60) : null;

  const cleanChartStatus = (chartStatus || '').toLowerCase();
  const isChartPrepared = cleanChartStatus.includes('chart prepared') && !cleanChartStatus.includes('not prepared');

  // Flat charge & WL/RAC clerkage lookup
  const flatCfg = MIN_FLAT_CHARGES[resolvedClass] || MIN_FLAT_CHARGES['SL'];
  const gstRate = flatCfg.hasGst ? 0.05 : 0;
  const flatPerPax = flatCfg.charge;
  const clerkageBasePerPax = WL_RAC_CLERKAGE_CHARGE;
  const clerkageGstPerPax = flatCfg.hasGst ? Math.round(clerkageBasePerPax * gstRate) : 0;
  const clerkageTotalPerPax = clerkageBasePerPax + clerkageGstPerPax;

  // Time format helper (e.g., 31:54 hr)
  const formatTimeRemaining = (hrs: number | null) => {
    if (hrs === null) return 'Departure time unavailable';
    if (hrs <= 0) return 'Departed';
    const totalMinutes = Math.floor(hrs * 60);
    const h = Math.floor(totalMinutes / 60);
    const m = totalMinutes % 60;
    return `${h}:${m.toString().padStart(2, '0')} hr`;
  };
  const timeUntilDepartureText = formatTimeRemaining(hoursUntilDeparture);

  // ── SLAB CALCULATIONS (Computed only when fareAvailable === true) ────────
  const otherActivePaxCount = Math.max(
    0,
    passengers.length - cnfPaxCount - wlRacPaxCount - nosbPaxCount - canPaxCount
  );

  const computeSlabPair = (pct: number) => {
    if (baseFare === null || isAllCancelled) return { deduction: null, refund: null };

    if (isPureWlRac) {
      // Unconfirmed WL / RAC tickets incur flat clerkage (₹60 + 5% GST for AC / ₹60 non-AC)
      // across >48h, 48h–12h, and 12h–4h windows — never confirmed flat/25%/50% slabs.
      const eligibleWlPax = Math.max(1, wlRacPaxCount + nosbPaxCount + otherActivePaxCount);
      const deduction = Math.min(baseFare, clerkageTotalPerPax * eligibleWlPax);
      const refund = Math.max(0, baseFare - deduction);
      return { deduction, refund };
    }

    if (isMixedCnfAndWlRac) {
      const cnfEligiblePax = cnfPaxCount + nosbPaxCount + otherActivePaxCount;
      const totalActivePax = Math.max(1, cnfEligiblePax + wlRacPaxCount);
      const farePerPax = baseFare / totalActivePax;
      const cnfPerPaxDed = pct === 0 ? flatPerPax : Math.round(Math.max(farePerPax * pct, flatPerPax));
      const cnfPerPaxGst = flatCfg.hasGst ? Math.round(cnfPerPaxDed * gstRate) : 0;
      const cnfTotalDed = (cnfPerPaxDed + cnfPerPaxGst) * cnfEligiblePax;
      const wlTotalDed = clerkageTotalPerPax * wlRacPaxCount;
      const deduction = Math.min(baseFare, cnfTotalDed + wlTotalDed);
      const refund = Math.max(0, baseFare - deduction);
      return { deduction, refund };
    }

    // D-02: Exclude already-cancelled/modified/released passengers from chargeable confirmed count
    // without inflating per-passenger fare across remaining passengers.
    const chargeableCnfPax = passengers.length === 0 ? 1 : Math.max(0, passengers.length - canPaxCount);
    if (chargeableCnfPax === 0) return { deduction: null, refund: null };
    const farePerPax = paxCount > 0 ? baseFare / paxCount : baseFare;
    const perPaxDed = pct === 0 ? flatPerPax : Math.round(Math.max(farePerPax * pct, flatPerPax));
    const perPaxGst = flatCfg.hasGst ? Math.round(perPaxDed * gstRate) : 0;
    const deduction = Math.min(baseFare, (perPaxDed + perPaxGst) * chargeableCnfPax);
    const refund = Math.max(0, baseFare - deduction);
    return { deduction, refund };
  };

  const s1 = computeSlabPair(0);
  const s2 = computeSlabPair(0.25);
  const s3 = computeSlabPair(0.50);
  const s4Deduction = baseFare !== null && !isAllCancelled ? baseFare : null;
  const s4Refund = baseFare !== null && !isAllCancelled ? 0 : null;

  const clerkageLabel = flatCfg.hasGst
    ? `₹${clerkageBasePerPax} + 5% GST (₹${clerkageTotalPerPax})`
    : `₹${clerkageBasePerPax}`;

  // Determine active slab strictly from verified timing / charting
  const canEvaluateTimingSlab = isChartPrepared || hoursUntilDeparture !== null;
  const isSlab4 = isChartPrepared || (hoursUntilDeparture !== null && hoursUntilDeparture < 4);
  const isSlab3 = !isSlab4 && hoursUntilDeparture !== null && hoursUntilDeparture >= 4 && hoursUntilDeparture < 12;
  const isSlab2 = !isSlab4 && !isSlab3 && hoursUntilDeparture !== null && hoursUntilDeparture >= 12 && hoursUntilDeparture <= 48;
  const isSlab1 = !isSlab4 && !isSlab3 && !isSlab2 && hoursUntilDeparture !== null && hoursUntilDeparture > 48;

  let currentRefund: number | null = null;
  let currentDeduction: number | null = null;
  let currentSlabLabel = '';
  let currentSlabWindow = '';
  let explanation = '';

  if (isAllCancelled) {
    currentRefund = null;
    currentDeduction = null;
    currentSlabLabel = 'Already Cancelled';
    currentSlabWindow = 'Cancelled / Released';
    explanation = 'All passengers on this PNR are already cancelled, modified, or released. No further cancellation deduction applies.';
  } else if (!canEvaluateTimingSlab) {
    currentRefund = null;
    currentDeduction = null;
    currentSlabLabel = 'Departure time unavailable';
    currentSlabWindow = 'Timing pending';
    explanation = 'Exact cancellation window cannot be determined until departure time is available.';
  } else if (isSlab4) {
    if (isWaitlistedOrRAC && !isConfirmed) {
      currentRefund = null;
      currentDeduction = null;
      currentSlabLabel = isChartPrepared ? 'Clerkage Rules (Chart Prepared)' : 'Clerkage Rules (WL / RAC)';
      currentSlabWindow = isChartPrepared ? 'Charted · WL / RAC' : 'Under 04:00 hr · WL / RAC';
      explanation =
        'Confirmed-ticket 100% forfeiture does not apply to unconfirmed WL/RAC tickets; IRCTC clerkage rules apply based on cancellation channel and cutoff timing.';
    } else if (isWaitlistedOrRAC && isConfirmed) {
      currentRefund = null;
      currentDeduction = null;
      currentSlabLabel = isChartPrepared ? 'Mixed · Partial Clerkage Applies' : 'Mixed · Under 04:00 hr';
      currentSlabWindow = isChartPrepared ? 'Charted · Mixed Status' : 'Under 04:00 hr · Mixed Status';
      explanation =
        'Confirmed passengers carry no refund after chart preparation or within 4 hours of departure; unconfirmed WL/RAC passengers remain governed by IRCTC clerkage rules.';
    } else {
      currentRefund = s4Refund;
      currentDeduction = s4Deduction;
      currentSlabLabel = isChartPrepared ? 'Chart Prepared' : 'Less than 4:00 hr';
      currentSlabWindow = 'Under 04:00 hr or charted';
      explanation = isChartPrepared
        ? 'The chart is prepared. Confirmed tickets carry no refund after chart preparation.'
        : 'Under 4 hours until departure. No standard refund after this point.';
    }
  } else if (isSlab3) {
    currentRefund = s3.refund;
    currentDeduction = s3.deduction;
    currentSlabLabel = '12:00 hr – 4:00 hr';
    currentSlabWindow = '12:00 hr to 04:00 hr';
    explanation = isPureWlRac
      ? `WL/RAC clerkage of ${clerkageLabel} per passenger applies (percentage slabs apply only to confirmed tickets).`
      : isMixedCnfAndWlRac
        ? `50% slab applies to confirmed passengers; ${clerkageLabel} clerkage applies to unconfirmed WL/RAC passengers.`
        : '50% of fare, subject to the flat minimum cancellation charge.';
  } else if (isSlab2) {
    currentRefund = s2.refund;
    currentDeduction = s2.deduction;
    currentSlabLabel = '48:00 hr – 12:00 hr';
    currentSlabWindow = '48:00 hr to 12:00 hr';
    explanation = isPureWlRac
      ? `WL/RAC clerkage of ${clerkageLabel} per passenger applies (percentage slabs apply only to confirmed tickets).`
      : isMixedCnfAndWlRac
        ? `25% slab applies to confirmed passengers; ${clerkageLabel} clerkage applies to unconfirmed WL/RAC passengers.`
        : '25% of fare, subject to the flat minimum cancellation charge.';
  } else {
    currentRefund = s1.refund;
    currentDeduction = s1.deduction;
    currentSlabLabel = 'More than 48:00 hr';
    currentSlabWindow = 'More than 48:00 hrs';
    explanation = isPureWlRac
      ? `WL/RAC clerkage of ${clerkageLabel} per passenger applies.`
      : isMixedCnfAndWlRac
        ? `Flat ₹${flatPerPax} applies to confirmed passengers; ${clerkageLabel} clerkage applies to WL/RAC passengers.`
        : `Flat ₹${flatPerPax} per passenger minimum cancellation fee applies.`;
  }

  if (!fareAvailable && canEvaluateTimingSlab) {
    explanation = `Fare details unavailable. ${explanation}`;
  }

  const slabs: RefundSlab[] = [
    {
      key: 'gt48',
      label: 'More than 48:00 hr',
      timeWindow: '> 48:00 hr',
      deductionAmount: s1.deduction,
      refundAmount: s1.refund,
      percentageText: isPureWlRac
        ? `WL/RAC clerkage: ${clerkageLabel} per passenger`
        : isMixedCnfAndWlRac
          ? `CNF: ₹${flatPerPax} flat · WL/RAC: ${clerkageLabel}`
          : `Flat ₹${flatPerPax} per passenger`,
      isActive: isSlab1,
      notes: isPureWlRac
        ? `Official IRCTC clerkage charge for unconfirmed WL/RAC (${resolvedClass}).`
        : `Flat minimum cancellation fee for ${resolvedClass}.`
    },
    {
      key: '48to12',
      label: '48:00 hr – 12:00 hr',
      timeWindow: '48:00 hr to 12:00 hr',
      deductionAmount: s2.deduction,
      refundAmount: s2.refund,
      percentageText: isPureWlRac
        ? `WL/RAC clerkage: ${clerkageLabel} per passenger`
        : isMixedCnfAndWlRac
          ? `CNF: 25% of fare · WL/RAC: ${clerkageLabel}`
          : '25% of fare, subject to the flat minimum',
      isActive: isSlab2,
      notes: isPureWlRac
        ? 'Unconfirmed WL/RAC tickets incur flat clerkage only.'
        : '25% of ticket fare deducted.'
    },
    {
      key: '12to4',
      label: '12:00 hr – 4:00 hr',
      timeWindow: '12:00 hr to 04:00 hr',
      deductionAmount: s3.deduction,
      refundAmount: s3.refund,
      percentageText: isPureWlRac
        ? `WL/RAC clerkage: ${clerkageLabel} per passenger`
        : isMixedCnfAndWlRac
          ? `CNF: 50% of fare · WL/RAC: ${clerkageLabel}`
          : '50% of fare, subject to the flat minimum',
      isActive: isSlab3,
      notes: isPureWlRac
        ? 'Unconfirmed WL/RAC tickets incur flat clerkage only.'
        : '50% of ticket fare deducted.'
    },
    {
      key: 'lt4',
      label: 'Less than 4:00 hr',
      timeWindow: 'Under 04:00 hr or charted',
      deductionAmount: isWaitlistedOrRAC ? null : s4Deduction,
      refundAmount: isWaitlistedOrRAC ? null : s4Refund,
      percentageText: isWaitlistedOrRAC
        ? (!isConfirmed
            ? 'Subject to IRCTC clerkage rules (not ₹0 forfeiture)'
            : 'Confirmed portion forfeited; WL/RAC clerkage applies')
        : 'No standard refund after this point',
      isActive: isSlab4,
      notes: isWaitlistedOrRAC
        ? 'Unconfirmed WL/RAC tickets are governed by IRCTC clerkage rules.'
        : 'Zero refund after chart preparation / within 4 hrs.'
    }
  ];

  let tatkalAdvisory: string | undefined = undefined;
  if (isTatkal) {
    tatkalAdvisory = isConfirmed
      ? 'Confirmed Tatkal tickets generally carry no refund on passenger cancellation under strict IRCTC rules. Standard time-based estimate is shown above for estimation and reference.'
      : 'Waitlisted Tatkal (TQWL) tickets qualify for a full refund minus flat clerkage charges if not confirmed.';
  }

  return {
    pnrNumber: pnr,
    fareAvailable,
    departureTimeAvailable,
    isTatkal,
    isConfirmed,
    isWaitlistedOrRAC,
    ticketFare: baseFare,
    passengerCount: paxCount,
    travelClass: resolvedClass,
    quota: quotaRaw || (isTatkal ? 'TQ' : ''),
    hoursUntilDeparture,
    currentRefund,
    currentDeduction,
    currentSlabLabel,
    currentSlabWindow,
    timeUntilDepartureText,
    explanation,
    tatkalAdvisory,
    slabs
  };
}
