/**
 * CT-06B Zero-DB Quick Wins: PNR Privacy Masking & Freshness Formatting Helpers
 * Pure deterministic utilities with zero network calls and zero side effects.
 */

export function maskPnrNumber(pnr: string): string {
  const clean = String(pnr || '').replace(/\D/g, '');
  if (!clean) return '••••••••••';
  if (clean.length <= 4) return '•'.repeat(clean.length);
  return `${'X'.repeat(clean.length - 4)}${clean.slice(-4)}`;
}

export function formatPnrForShare(pnr: string, includeFullPnr: boolean): string {
  const raw = String(pnr || '').trim();
  if (!raw) return '••••••••••';
  return includeFullPnr ? raw : maskPnrNumber(raw);
}

export function formatShareUrlForPnr(
  pnr: string,
  fullPnrUrl: string,
  includeFullPnr: boolean,
  fallbackBaseUrl: string = 'https://www.trayago.in/pnr'
): string {
  if (includeFullPnr && fullPnrUrl) return fullPnrUrl;
  return fallbackBaseUrl;
}

export function formatCheckedAtBadge(checkedAt?: string | null): string | null {
  if (!checkedAt || typeof checkedAt !== 'string') return null;
  const trimmed = checkedAt.trim();
  if (!trimmed) return null;
  const parsed = new Date(trimmed);
  if (isNaN(parsed.getTime())) return null;

  const hours24 = parsed.getHours();
  const minutes = parsed.getMinutes();
  const ampm = hours24 >= 12 ? 'PM' : 'AM';
  const hours12 = hours24 % 12 || 12;
  const minsStr = String(minutes).padStart(2, '0');
  return `Updated ${hours12}:${minsStr} ${ampm}`;
}
