import { trackEvent } from '../lib/api';

/**
 * Robust WhatsApp share helper with a bulletproof mobile-first fallback chain:
 * 1. navigator.share() (Native Share Drawer with Timeout protection)
 * 2. whatsapp://send (Direct Deep-Link with blur-detection app presence check)
 * 3. https://wa.me/ (Universal meta redirection link - popup-blocker safe)
 * 4. Clipboard Copy fallback (Copies text to user clipboard if all else fails)
 * 5. Dynamic HTML DOM Toasts (Beautiful premium dark glass UI alerts)
 */
export async function shareToWhatsApp(text: string) {
  if (typeof window === 'undefined') return;

  const encodedText = encodeURIComponent(text);
  const isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(
    navigator.userAgent
  );

  // Auto-copy text as a silent backdrop fallback so it's always ready on the user's clipboard
  try {
    await navigator.clipboard.writeText(text);
  } catch (e) {
    // Silent fail for backdrop copy
  }

  // ── 1. NATIVE SHARE (Mobile Secure Contexts) ──
  if (isMobile && navigator.share) {
    try {
      showDOMToast('Launching native share...', 'info');
      trackEvent('share_native_attempt', undefined, { text });

      // Wrap native share in a 4-second promise race to prevent UI freeze
      const sharePromise = navigator.share({
        title: 'Trayago Share',
        text: text,
      });

      const timeoutPromise = new Promise((_, reject) =>
        setTimeout(() => reject(new Error('TIMEOUT')), 4000)
      );

      await Promise.race([sharePromise, timeoutPromise]);

      trackEvent('share_native_success');
      showDOMToast('Shared successfully!', 'success');
      return;
    } catch (err: any) {
      if (err.name === 'AbortError' || err.message === 'Share canceled') {
        // User dismissed the native share drawer - respect choice, stop chain
        trackEvent('share_native_cancelled');
        showDOMToast('Share cancelled', 'info');
        return;
      }

      console.warn('Native share failed or timed out. Falling back to deep link:', err);
      trackEvent('share_native_failed', undefined, {
        error: err.message || err.toString(),
        name: err.name,
      });
    }
  }

  // ── 2. WHATSAPP MOBILE DEEP LINK (whatsapp://send) ──
  if (isMobile) {
    showDOMToast('Opening WhatsApp...', 'info');
    trackEvent('share_deeplink_attempt', undefined, { text });

    const whatsappUrl = `whatsapp://send?text=${encodedText}`;
    const waMeUrl = `https://api.whatsapp.com/send?text=${encodedText}`;

    let blurred = false;
    const handleBlur = () => {
      blurred = true;
    };

    window.addEventListener('blur', handleBlur);

    try {
      window.location.href = whatsappUrl;
    } catch (err: any) {
      window.removeEventListener('blur', handleBlur);
      trackEvent('share_deeplink_error', undefined, { error: err.message });
      triggerUniversalMobileLink(waMeUrl, text);
      return;
    }

    // Check if browser blurred within 1.2s. If not, the app isn't installed.
    setTimeout(() => {
      window.removeEventListener('blur', handleBlur);
      if (!blurred) {
        trackEvent('share_deeplink_failed_no_app', undefined, { text });
        // Fallback to direct api.whatsapp.com universal link
        triggerUniversalMobileLink(waMeUrl, text);
      } else {
        trackEvent('share_deeplink_success');
      }
    }, 1200);

    return;
  }

  // ── 3. DESKTOP / SANDBOX FALLBACK (Direct WhatsApp Web) ──
  try {
    showDOMToast('Opening WhatsApp Web...', 'info');
    trackEvent('share_wame_desktop_attempt');

    // Direct WhatsApp Web URL avoids Meta 302 redirect header emoji corruption
    const desktopUrl = `https://web.whatsapp.com/send?text=${encodedText}`;

    // Secure window launch inside synchronous gesture context
    const newWindow = window.open(desktopUrl, '_blank', 'noopener,noreferrer');

    if (!newWindow || newWindow.closed || typeof newWindow.closed === 'undefined') {
      throw new Error('POPUP_BLOCKED');
    }

    trackEvent('share_wame_desktop_success');
  } catch (err: any) {
    console.warn('Desktop universal link failed or popup blocked:', err);
    trackEvent('share_wame_desktop_failed', undefined, { error: err.message });
    triggerClipboardFallback(text);
  }
}

/**
 * Mobile-first universal redirect fallback (100% immune to popup blockers)
 */
function triggerUniversalMobileLink(waMeUrl: string, originalText: string) {
  try {
    trackEvent('share_wame_mobile_attempt');
    window.location.href = waMeUrl;
  } catch (err: any) {
    console.error('Universal mobile redirect failed:', err);
    trackEvent('share_wame_mobile_failed', undefined, { error: err.message });
    triggerClipboardFallback(originalText);
  }
}

/**
 * Clipboard fallback copy with elegant feedback toast
 */
async function triggerClipboardFallback(text: string) {
  try {
    await navigator.clipboard.writeText(text);
    showDOMToast('Referral link copied to clipboard! Paste it inside WhatsApp.', 'success');
    trackEvent('share_clipboard_fallback_success');
  } catch (err: any) {
    console.error('Final clipboard fallback failed:', err);
    trackEvent('share_clipboard_fallback_failed', undefined, { error: err.message });
    showDOMToast('Please copy your code manually from the screen.', 'error');
  }
}

/**
 * Dynamic, self-contained glassmorphic DOM toast for instant feedback without React dependencies.
 */
export function showDOMToast(message: string, type: 'success' | 'error' | 'info') {
  if (typeof document === 'undefined') return;

  const toastId = 'trayago-share-toast';
  const existing = document.getElementById(toastId);
  if (existing) {
    existing.remove();
  }

  const container = document.createElement('div');
  container.id = toastId;
  container.className = `
    fixed z-[99999] px-5 py-3.5 rounded-2xl shadow-[0_10px_30px_rgba(0,0,0,0.5)] border backdrop-blur-lg
    flex items-center gap-3 transition-all duration-300 transform -translate-x-1/2
    left-1/2 max-w-[90%] sm:max-w-md w-max
  `;

  // Enter animation style
  container.style.opacity = '0';
  container.style.transform = 'translate(-50%, -20px)';
  container.style.transition = 'all 0.3s cubic-bezier(0.16, 1, 0.3, 1)';

  // Style colors and shadows based on toast types
  if (type === 'success') {
    container.style.backgroundColor = 'rgba(9, 9, 11, 0.9)'; // Zinc 950
    container.style.borderColor = 'rgba(16, 185, 129, 0.4)'; // Emerald
    container.style.color = '#ffffff';
    container.style.boxShadow = '0 10px 40px rgba(16, 185, 129, 0.15)';
  } else if (type === 'error') {
    container.style.backgroundColor = 'rgba(9, 9, 11, 0.9)';
    container.style.borderColor = 'rgba(239, 68, 68, 0.4)'; // Rose
    container.style.color = '#ffffff';
    container.style.boxShadow = '0 10px 40px rgba(239, 68, 68, 0.15)';
  } else {
    container.style.backgroundColor = 'rgba(9, 9, 11, 0.9)';
    container.style.borderColor = 'rgba(255, 255, 255, 0.1)';
    container.style.color = '#ffffff';
  }

  // Positioning: top on mobile (to clear bottom nav), bottom on desktop
  const isMobile = window.innerWidth < 768;
  if (isMobile) {
    container.style.top = '80px';
  } else {
    container.style.bottom = '96px';
  }

  // Set premium Lucide-styled SVG icons
  let iconSVG = '';
  if (type === 'success') {
    iconSVG = `
      <svg class="w-5 h-5 text-emerald-400 shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="3">
        <path stroke-linecap="round" stroke-linejoin="round" d="M5 13l4 4L19 7" />
      </svg>
    `;
  } else if (type === 'error') {
    iconSVG = `
      <svg class="w-5 h-5 text-rose-400 shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="3">
        <path stroke-linecap="round" stroke-linejoin="round" d="M6 18L18 6M6 6l12 12" />
      </svg>
    `;
  } else {
    iconSVG = `
      <svg class="w-5 h-5 text-blue-500 shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="3">
        <path stroke-linecap="round" stroke-linejoin="round" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
      </svg>
    `;
  }

  container.innerHTML = `
    ${iconSVG}
    <span class="text-xs font-bold tracking-wide">${message}</span>
  `;

  document.body.appendChild(container);

  // Trigger smooth browser entry animation
  requestAnimationFrame(() => {
    container.style.opacity = '1';
    container.style.transform = 'translate(-50%, 0)';
  });

  // Self-remove with fade-out
  setTimeout(() => {
    container.style.opacity = '0';
    container.style.transform = 'translate(-50%, -20px)';
    setTimeout(() => {
      container.remove();
    }, 300);
  }, 4000);
}
